import{_ as e,o as l,c as i,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Tech Talk 2020-08-20- Edge Application - Streaming Multiple Video Sources","description":"","frontmatter":{"title":"Ceph Tech Talk 2020-08-20- Edge Application - Streaming Multiple Video Sources","date":"2020-08-20T00:00:00.000Z","updated":"2020-08-21T00:00:00.000Z","tags":["边缘计算","Ceph","视频流","分布式存储","OpenCV"],"categories":["技术会议"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/Ceph_Tech_Talk_2020-08-20_-_Edge_Application_-_Streaming_Multiple_Video_Sources.md","filePath":"posts/2020/Ceph_Tech_Talk_2020-08-20_-_Edge_Application_-_Streaming_Multiple_Video_Sources.md","lastUpdated":1780459816000}'),r={name:"posts/2020/Ceph_Tech_Talk_2020-08-20_-_Edge_Application_-_Streaming_Multiple_Video_Sources.md"};function o(h,a,n,p,d,s){return l(),i("div",null,[...a[0]||(a[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-ceph-tech-talk-边缘应用多视频源流式传输项目介绍" tabindex="-1">会议主题：Ceph Tech Talk - 边缘应用多视频源流式传输项目介绍 <a class="header-anchor" href="#会议主题-ceph-tech-talk-边缘应用多视频源流式传输项目介绍" aria-label="Permalink to &quot;会议主题：Ceph Tech Talk - 边缘应用多视频源流式传输项目介绍&quot;">​</a></h4><h4 id="会议时间-2020年8月20日" tabindex="-1">会议时间：2020年8月20日 <a class="header-anchor" href="#会议时间-2020年8月20日" aria-label="Permalink to &quot;会议时间：2020年8月20日&quot;">​</a></h4><h4 id="会议地点-线上会议" tabindex="-1">会议地点：线上会议 <a class="header-anchor" href="#会议地点-线上会议" aria-label="Permalink to &quot;会议地点：线上会议&quot;">​</a></h4><h4 id="主持人-mike-perez-社区经理-red-hat新兴技术部门" tabindex="-1">主持人：Mike Perez（社区经理，Red Hat新兴技术部门） <a class="header-anchor" href="#主持人-mike-perez-社区经理-red-hat新兴技术部门" aria-label="Permalink to &quot;主持人：Mike Perez（社区经理，Red Hat新兴技术部门）&quot;">​</a></h4><h4 id="参会人员-jason-wang、niharika-kompala-red-hat实习生-、其他未具名观众" tabindex="-1">参会人员：Jason Wang、Niharika Kompala（Red Hat实习生）、其他未具名观众 <a class="header-anchor" href="#参会人员-jason-wang、niharika-kompala-red-hat实习生-、其他未具名观众" aria-label="Permalink to &quot;参会人员：Jason Wang、Niharika Kompala（Red Hat实习生）、其他未具名观众&quot;">​</a></h4><h4 id="会议内容总结" tabindex="-1">会议内容总结： <a class="header-anchor" href="#会议内容总结" aria-label="Permalink to &quot;会议内容总结：&quot;">​</a></h4><ol><li><p><strong>项目介绍</strong>：</p><ul><li>Jason Wang和Niharika Kompala作为Red Hat的实习生，介绍了他们在夏季实习期间开发的边缘应用项目，该项目涉及多视频源的流式传输。</li><li>项目目标是通过边缘计算技术改善视频流的质量和延迟问题，特别是处理大量摄像头数据时。</li></ul></li><li><p><strong>技术背景</strong>：</p><ul><li>讨论了边缘计算的重要性，特别是在预计到2025年将有750亿连接设备的大数据量背景下。</li><li>强调了边缘计算在提供低延迟和高速度处理方面的优势。</li></ul></li><li><p><strong>项目架构与技术实现</strong>：</p><ul><li>项目使用了GStreamer框架来处理视频流，并开发了自定义的GStreamer插件来上传视频到Ceph存储系统。</li><li>利用Ceph的多部分上传功能和S3 API，实现了视频数据的同步和存储。</li><li>通过Knative函数触发器，实现了视频的拼接和分析处理，使用了OpenCV进行视频拼接。</li></ul></li><li><p><strong>演示与代码展示</strong>：</p><ul><li>展示了项目的实际运行情况，包括视频流的上传和拼接过程。</li><li>讨论了在Fedora系统上运行GStreamer时遇到的问题，并介绍了使用Ubuntu容器作为解决方案。</li></ul></li><li><p><strong>未来工作与感谢</strong>：</p><ul><li>提出了未来可能的扩展，如创建RGW NFS网关以支持RTMP视频流。</li><li>感谢Warman、Harrison以及Ceph团队的支持和帮助。</li></ul></li></ol><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>继续优化和扩展项目功能，特别是在Knative和Ceph的集成方面。</li><li>探索更多的边缘计算应用场景，以支持更广泛的视频流处理需求。</li></ul><h4 id="会议结束" tabindex="-1">会议结束： <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束：&quot;">​</a></h4><ul><li>会议在感谢和告别中结束，主持人预告了下一次的Tech Talk主题。</li></ul><h4 id="备注" tabindex="-1">备注： <a class="header-anchor" href="#备注" aria-label="Permalink to &quot;备注：&quot;">​</a></h4><ul><li>会议中提到的GitHub项目URL未在纪要中提供，建议后续补充。</li></ul><p>以上是本次Ceph Tech Talk的会议纪要，涵盖了会议的关键细节、讨论的主要议题、决定的事项以及后续的行动计划。</p>',15)])])}const u=e(r,[["render",o]]);export{c as __pageData,u as default};
